    limit = 100 # Set a reasonable limit for checking the "tested range"
    solutions = []

    # We are solving b^3 + c^3 = 503 * (bc + 1)

    for b in range(2, limit + 1):
        for c in range(b, limit + 1):
            LHS = b**3 + c**3
            RHS = 503 * (b * c + 1)

            if LHS == RHS:
                solutions.append((b, c))
                print(f"Found solution: ({b}, {c})")

    if not solutions:
        print("No solutions found in the range b <= 100.")
    return solutions

