import math

# Search for integer solutions to b^2 - bc + c^2 = 1006 (i.e., m=2)
# Discriminant Delta = 4*1006 - 3*b^2 = 4024 - 3*b^2.
b_min = 3
# b_max <= 36
b_max = 36

found_solutions = []

for b in range(b_min, b_max + 1):
    discriminant = 4024 - 3 * b**2
    if discriminant >= 0:
        d_float = math.sqrt(discriminant)
        d_int = int(round(d_float))

        if d_int * d_int == discriminant:
            if (b + d_int) % 2 == 0:
                c1 = (b + d_int) // 2
                if c1 >= b:
                    found_solutions.append((b, c1))

if found_solutions:
    print("Solutions found for m=2:")
    for sol in found_solutions:
        print(sol)
else:
    print("No solutions found for m=2.")
